algorithm.rustSketch:
fn lower_bound(values: &[i32], target: i32) -> usize {
    let (mut low, mut high) = (0, values.len());
    while low < high {
        let mid = low + (high - low) / 2;
        if values[mid] < target { low = mid + 1; } else { high = mid; }
    }
    low
}

